mapper.select:
select p.id as id, p.determination_type as determinationType, date_format(p.business_period, '%Y-%m') as businessPeriod, p.subsidy_type as subsidyType, p.batch_no as batchNo, p.total_count as totalCount, p.total_amount as totalAmount, p.operator_name as operatorName, p.operator_time as operatorTime, p.approval_status as approvalStatus, p.finance_status as financeStatus, p.distribution_status as distributionStatus, (select group_concat(distinct s.subsidy_type order by s.subsidy_type separator ',') from shebao_payment_plan_summary s where s.plan_id = p.id and s.del_flag = '0') as subsidyTypes, (select min(s.grant_org) from shebao_payment_plan_summary s where s.plan_id = p.id and s.del_flag = '0') as grantOrg from shebao_payment_plan p where p.del_flag = '0'
and p.batch_no = #{req.batchNo}
and p.determination_type = #{req.determinationType}
and p.subsidy_type = #{req.subsidyType}
and p.approval_status = #{req.approvalStatus}
and p.operator_name like concat('%', #{req.operatorName}, '%')
and p.business_period = #{req.businessPeriodDate}
and p.finance_status = #{req.financeStatus}
and ifnull(p.distribution_status, 'pending') = #{req.distributionStatus}
and p.finance_status is not null and p.finance_status != ''
order by p.create_time desc, p.id desc
